package android.view; import java.util.*; public class ViewTreeObserver { public interface OnWindowFocusChangeListener {void onWindowFocusChanged(boolean f);} final List<OnWindowFocusChangeListener> listeners=new ArrayList<>(); public void addOnWindowFocusChangeListener(OnWindowFocusChangeListener l){listeners.add(l);} public void focus(boolean f){for(OnWindowFocusChangeListener l:listeners)l.onWindowFocusChanged(f);} }
